const reverseToChinese = (dict: Record<string, string>): Record<string, string> =>
  Object.fromEntries(Object.entries(dict).map(([source, translated]) => [translated, source]));

const frenchToChineseDict = reverseToChinese(settingFrenchDict);
const englishToChineseDict = reverseToChinese(settingEnglishDict);

