// 动态模式翻译（数字、量词、提示、状态等）
const matchDynamicPatterns = (trimmed: string, lang: string): string | null => {
  const copiedMatch = trimmed.match(/^(.+) copié$/);
  if (copiedMatch) {
    const label = trSetting(copiedMatch[1]);
    if (lang === "en") return `${label} copied`;
    if (lang === "zh") return `${label}已复制`;
    return trimmed;
  }
  const emptySearchMatch = trimmed.match(
    /^Désolé, aucune? (titre|artiste|album|playlist|podcast|clip) trouvée? pour (.+)$/,
  );
  if (emptySearchMatch) {
    const [, type, keyword] = emptySearchMatch;
    const labels = {
      titre: { en: "track", zh: "歌曲" },
      artiste: { en: "artist", zh: "艺人" },
      album: { en: "album", zh: "专辑" },
      playlist: { en: "playlist", zh: "歌单" },
      podcast: { en: "podcast", zh: "播客" },
      clip: { en: "video", zh: "视频" },
    } as const;
    const label = labels[type as keyof typeof labels];
    if (lang === "en") return `Sorry, no ${label.en} found for ${keyword}`;
    if (lang === "zh") return `抱歉，未找到与 ${keyword} 相关的${label.zh}`;
    return trimmed;
  }
  // 榜单更新提示
  const updateCount = trimmed.match(/^更新\s*(\d+)\s*首(?:歌曲)?$/);
  if (updateCount) {
    const n = updateCount[1];
    return lang === "en" ? `Updated ${n} tracks` : `Mis à jour (${n} titres)`;
  }
  // 刚刚更新 / 每日更新
  if (/^刚刚更新|^刚刚/.test(trimmed)) {
    return lang === "en" ? "Just updated" : "Mis à jour à l'instant";
  }
  if (/^每天更新|^每日更新/.test(trimmed)) {
    return lang === "en" ? "Daily update" : "Mise à jour quotidienne";
  }
  // 每周X更新
  const weekMatch = trimmed.match(/^每周([一二三四五六日天])更新/);
  if (weekMatch) {
    // 星期映射
    const daysEn: Record<string, string> = {
      一: "Monday",
      二: "Tuesday",
      三: "Wednesday",
      四: "Thursday",
      五: "Friday",
      六: "Saturday",
      日: "Sunday",
      天: "Sunday",
    };
    const daysFr: Record<string, string> = {
      一: "lundi",
      二: "mardi",
      三: "mercredi",
      四: "jeudi",
      五: "vendredi",
      六: "samedi",
      日: "dimanche",
      天: "dimanche",
    };
    const day = weekMatch[1];
    return lang === "en" ? `Updated every ${daysEn[day]}` : `Mis à jour chaque ${daysFr[day]}`;
  }
  // 已发现 / 新增 / 已找到 / 已加载
  const foundMatch = trimmed.match(/^(?:已发现|新增|已找到|已加载)\s*(\d+)\s*首/);
  if (foundMatch) {
    const n = foundMatch[1];
    return lang === "en" ? `Found ${n} tracks` : `${n} titres trouvés`;
  }
  // 已选择 X 项
  const selectedMatch = trimmed.match(/^已选择\s*(\d+)\s*项/);
  if (selectedMatch) {
    const n = selectedMatch[1];
    return lang === "en" ? `${n} items selected` : `${n} éléments sélectionnés`;
  }
  // 共 X 首 / 张 / 个 / 位
  const totalMatch = trimmed.match(/^共\s*(\d+)\s*(首歌曲|首|张专辑|个歌单|位歌手|个视频|个播客)/);
  if (totalMatch) {
    const n = totalMatch[1];
    const unit = totalMatch[2];
    // 数量单位映射
    const unitEn: Record<string, string> = {
      首: "tracks",
      首歌曲: "tracks",
      张专辑: "albums",
      个歌单: "playlists",
      位歌手: "artists",
      个视频: "videos",
      个播客: "podcasts",
    };
    const unitFr: Record<string, string> = {
      首: "titres",
      首歌曲: "titres",
      张专辑: "albums",
      个歌单: "playlists",
      位歌手: "artistes",
      个视频: "vidéos",
      个播客: "podcasts",
    };
    return lang === "en"
      ? `${n} ${unitEn[unit] ?? "items"} in total`
      : `${n} ${unitFr[unit] ?? "éléments"} au total`;
  }
  // 最多保留 X 个账号
  const accountMatch = trimmed.match(/^最多只能保留\s*(\d+)\s*个账号/);
  if (accountMatch) {
    const n = accountMatch[1];
    return lang === "en" ? `You can keep up to ${n} accounts` : `Maximum ${n} comptes conservés`;
  }
  // 正在获取本地歌曲 (X/Y)
  const localMatch = trimmed.match(/^正在获取本地歌曲\s*\((\d+)\/(\d+)\)/);
  if (localMatch) {
    return lang === "en"
      ? `Loading local songs (${localMatch[1]}/${localMatch[2]})`
      : `Chargement des titres locaux (${localMatch[1]}/${localMatch[2]})`;
  }
  // 正在加载第 X 页
  const pageMatch = trimmed.match(/^正在加载第\s*(\d+)\s*页/);
  if (pageMatch) {
    const n = pageMatch[1];
    return lang === "en" ? `Loading page ${n}` : `Chargement de la page ${n}`;
  }
  // 第 X 期 / 第 X 首
  const periodMatch = trimmed.match(/^第\s*(\d+)\s*期/);
  if (periodMatch) {
    const n = periodMatch[1];
    return lang === "en" ? `Episode ${n}` : `Épisode ${n}`;
  }
  const trackNoMatch = trimmed.match(/^第\s*(\d+)\s*首/);
  if (trackNoMatch) {
    const n = trackNoMatch[1];
    return lang === "en" ? `Track ${n}` : `Titre ${n}`;
  }
  // 常见前缀处理
  const prefixMap: Record<string, { en: string; fr: string }> = {
    已连接到: { en: "Connected to ", fr: "Connecté à " },
  };
  for (const prefix of Object.keys(prefixMap)) {
    if (trimmed.startsWith(prefix)) {
      const rest = trimmed.slice(prefix.length);
      return lang === "en" ? prefixMap[prefix].en + rest : prefixMap[prefix].fr + rest;
    }
  }
  // 兜底：中文网络 / 操作提示
  if (/[一-鿿]/.test(trimmed)) {
    if (trimmed.includes("超时") || trimmed.includes("网络")) {
      return lang === "en"
        ? "Network request timed out, please check connection"
        : "Délai de requête réseau dépassé, vérifiez votre connexion";
    }
    if (trimmed.includes("失败")) {
      return lang === "en"
        ? "Operation failed, please try again"
        : "Échec de l'opération, veuillez réessayer";
    }
    if (trimmed.includes("成功")) {
      return lang === "en" ? "Operation successful" : "Opération réussie";
    }
  }

  return null;
};

/**
 * 翻译设置与全局文本（支持中文、英文、法文实时响应与动态拦截）
 */
export const trSetting = (text: any): any => {
  if (typeof text !== "string") return text;
  const trimmed = text.trim();
  if (!trimmed) return text;

  const settingStore = useSettingStore();
  const currentLang = settingStore?.language || "en";

  if (currentLang === "en") {
    if (settingEnglishDict[trimmed]) {
      return settingEnglishDict[trimmed];
    }
    if (frToEnDict[trimmed]) {
      return frToEnDict[trimmed];
    }
    const dynamicEn = matchDynamicPatterns(trimmed, "en");
    if (dynamicEn) return dynamicEn;
    if (trimmed.endsWith(":") || trimmed.endsWith("：")) {
      const base = trimmed.slice(0, -1);
      if (settingEnglishDict[base]) {
        return settingEnglishDict[base] + ": ";
      }
      if (frToEnDict[base]) {
        return frToEnDict[base] + ": ";
      }
    }
    return text;
  }

  if (currentLang === "zh") {
    if (settingChineseDict[trimmed]) {
      return settingChineseDict[trimmed];
    }
    if (frenchToChineseDict[trimmed]) {
      return frenchToChineseDict[trimmed];
    }
    if (englishToChineseDict[trimmed]) {
      return englishToChineseDict[trimmed];
    }
    const dynamicZh = matchDynamicPatterns(trimmed, "zh");
    if (dynamicZh) return dynamicZh;
    return text;
  }

  // 默认法语 (fr)
  if (settingFrenchDict[trimmed]) {
    return settingFrenchDict[trimmed];
  }
  if (enToFrDict[trimmed]) {
    return enToFrDict[trimmed];
  }
  const dynamicFr = matchDynamicPatterns(trimmed, "fr");
  if (dynamicFr) return dynamicFr;
  if (trimmed.endsWith(":") || trimmed.endsWith("：")) {
    const base = trimmed.slice(0, -1);
    if (settingFrenchDict[base]) {
      return settingFrenchDict[base] + " : ";
    }
    if (enToFrDict[base]) {
      return enToFrDict[base] + " : ";
    }
  }

  return text;
};

export default trSetting;
